export function createLocalManagementUI({api,esc,openDialog,closeDialog,toast,getState,refresh}) {
 let sellerId='',operatorEmail='',epoch=0,active=false,tab='accounts',accounts=[],products=[],businesses=[],notifications=[],events=[],preview=null;
 const money=n=>(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
 const date=n=>n?new Date(n).toLocaleString('pt-BR'):'—';
 const button=(label,action,id='',kind='')=>`<button class="p-button secondary" data-lm-action="${action}" data-id="${esc(id)}" data-kind="${esc(kind)}">${label}</button>`;
 const notifyButton=id=>button('Notificar responsável','notify',id);
 function page(){return `<div class="local-management"><div id="lm-summary" class="lm-summary"></div><nav class="lm-tabs" aria-label="Gestão da Helpu Local">${[['accounts','Contas'],['businesses','Empresas'],['products','Produtos'],['activity','Atividade']].map(([id,label])=>`<button class="p-button secondary" data-lm-tab="${id}" aria-pressed="${id===tab}">${label}</button>`).join('')}</nav><div id="lm-panel"><p role="status">Carregando contas e produtos…</p></div></div>`;}
 function select(next){tab=next;const companies=document.querySelector('#local-business-panel');if(companies)companies.hidden=tab!=='businesses';for(const el of document.querySelectorAll('[data-lm-tab]')){el.setAttribute('aria-pressed',String(el.dataset.lmTab===tab));el.className='p-button '+(el.dataset.lmTab===tab?'primary':'secondary');}draw();}
 function toolbar(){return `${tab==='products'&&sellerId?'<p>Produtos de '+esc(businesses.find(b=>b.id===sellerId)?.name||'anunciante')+' '+button('Mostrar todos','clear-seller')+'</p>':''}<div class="lm-toolbar"><label>Buscar ${tab==='accounts'?'conta':'produto'}<input id="lm-search" type="search" placeholder="Nome, e-mail ou anúncio"></label><label>Situação<select id="lm-filter"><option value="">Todas</option>${(tab==='accounts'?['Ativo','Bloqueado','Convite pendente']:['Em análise','Publicado','Rascunho','Rejeitado','Pausado','Vendido','Excluído']).map(s=>`<option>${s}</option>`).join('')}</select></label>${tab==='accounts'?button('Limpar contas de teste','cleanup-start'):''}</div><p id="lm-count" role="status"></p><div id="lm-list" class="lm-grid"></div>`;}
 function draw(){if(!active)return;const root=document.querySelector('#lm-panel');if(!root)return;root.hidden=tab==='businesses';if(tab==='businesses')return;
  if(tab==='activity') {const history=[...events.map(e=>({at:e.createdAt,label:e.action,target:e.target,reason:e.reason})),...businesses.flatMap(b=>(b.history||[]).map(h=>({...h,label:h.action,target:b.name}))),...products.flatMap(p=>(p.history||[]).map(h=>({...h,label:'Produto: '+h.state,target:p.title})))].sort((a,b)=>b.at-a.at).slice(0,200);root.innerHTML=`<h2>Histórico da operação</h2><p>Últimas 200 ações registradas, incluindo alterações dos anunciantes e decisões da equipe.</p><div class="lm-timeline">${history.map(h=>`<article><time>${date(h.at)}</time><h3>${esc(h.label)}</h3><p>${esc(h.target)}${h.reason?' · '+esc(h.reason):''}</p></article>`).join('')||'<p>Nenhuma atividade registrada.</p>'}</div><h2>Notificações enviadas pelo portal</h2>${notifications.map(n=>`<article class="admin-box"><strong>${esc(n.title)}</strong><p>${esc(businesses.find(b=>b.id===n.businessId)?.name||'Cadastro preservado')}</p><p class="preserve-lines">${esc(n.message)}</p><small>${date(n.createdAt)} · ${n.readAt?'Lida em '+date(n.readAt):'Aguardando leitura'}</small></article>`).join('')||'<p>Nenhuma notificação enviada.</p>'}`;return;}
  root.innerHTML=toolbar();drawList();
 }
 function drawList(){if(!active||!['accounts','products'].includes(tab))return;const q=(document.querySelector('#lm-search')?.value||'').toLocaleLowerCase('pt-BR'),state=document.querySelector('#lm-filter')?.value;
  const items=(tab==='accounts'?accounts:products).filter(r=>{const status=tab==='accounts'?(r.blocked?'Bloqueado':r.activated?'Ativo':'Convite pendente'):r.state;return (tab!=='products'||!sellerId||r.businessId===sellerId)&&(!state||status===state)&&[r.name,r.email,r.title,r.sellerName,r.type].filter(Boolean).join(' ').toLocaleLowerCase('pt-BR').includes(q);});
  document.querySelector('#lm-count').textContent=items.length+(tab==='accounts'?' conta(s)':' produto(s)');
  document.querySelector('#lm-list').innerHTML=items.map(r=>tab==='accounts'?`<article class="admin-box lm-card"><div class="lm-card-top"><span class="p-tag">${esc(r.type)}</span><span class="p-tag">${r.protected?'Acesso protegido':r.blocked?'Bloqueado':r.activated?'Ativo':'Convite pendente'}</span></div><h2>${esc(r.name)}</h2><p class="lm-email">${esc(r.email)}</p><p>${r.kind==='local'?'Portal Helpu Local':'Marketing e administração'} · ${date(r.createdAt)}</p>${r.reason?`<p>${esc(r.reason)}</p>`:''}<div class="lm-actions">${r.businessId?notifyButton(r.businessId)+button('Ver produtos','seller-products',r.businessId):''}${r.protected?'':button(r.blocked?'Desbloquear acesso':'Bloquear acesso',r.blocked?'unblock':'block',r.id,r.kind)+button('Excluir conta','delete-account',r.id,r.kind)}</div></article>`:`<article class="admin-box lm-card"><div class="lm-card-top"><span class="p-tag">${esc(r.state)}</span><span>${esc(r.condition)}</span></div><h2>${esc(r.title)}</h2><strong>${money(r.priceCents)}</strong><p>${esc(r.sellerName)} · ${esc(r.sellerType)}</p><p>${esc(r.category)} · ${esc(r.city)}</p>${r.moderationReason?`<p>${esc(r.moderationReason)}</p>`:''}<div class="lm-actions">${button('Conferir anúncio','product',r.id)}${notifyButton(r.businessId)}${button(r.deletedAt?(r.soldAt?'Restaurar como encerrado':'Restaurar rascunho'):'Excluir anúncio',r.deletedAt?'restore-product':'delete-product',r.id)}</div></article>`).join('')||'<p class="admin-box">Nenhum resultado para esta busca.</p>';
 }
 async function load(rows){const ticket=++epoch;businesses=rows;const [control,list]=await Promise.all([api('/api/portal/local-control'),api('/api/portal/local-products')]);if(!active||ticket!==epoch)return;operatorEmail=control.operatorEmail;accounts=control.accounts;notifications=control.notifications;events=control.events;products=list.products;document.querySelector('#lm-summary').innerHTML=[['Contas',accounts.length],['Empresas no catálogo',businesses.filter(b=>!b.productsOnly&&!b.deletedAt).length],['Aguardando revisão',products.filter(p=>p.state==='Em análise').length+businesses.filter(b=>!b.productsOnly&&b.state==='Em análise').length],['Produtos publicados',products.filter(p=>p.state==='Publicado'&&businesses.some(b=>b.id===p.businessId&&b.state!=='Inativo')).length]].map(([label,n])=>`<div class="admin-box"><strong>${n}</strong><span>${label}</span></div>`).join('');select(tab);}
 function form(title,body,attrs=''){openDialog(title,`<form id="lm-form" ${attrs}>${body}<p role="alert"></p><button class="p-button primary">Confirmar</button></form>`,true);}
 const reasonField='<label>Motivo / orientação<textarea name="reason" required minlength="5" maxlength="1000"></textarea></label>';
 document.addEventListener('click',async e=>{if(!active)return;const nav=e.target.closest('[data-lm-tab]');if(nav){sellerId='';select(nav.dataset.lmTab);return;}const b=e.target.closest('[data-lm-action]');if(!b)return;const {lmAction:action,id,kind}=b.dataset;
  try {
   if(action==='clear-seller'){sellerId='';draw();return;}
   if(action==='seller-products'){sellerId=id;select('products');return;}
   if(action==='notify'){form('Notificar responsável',`<p>${esc(businesses.find(b=>b.id===id)?.name||'Anunciante')}</p><p>A mensagem será exibida dentro do portal. Não envia e-mail ou WhatsApp.</p><label>Título<input name="title" required minlength="3" maxlength="120"></label><label>Mensagem<textarea name="message" required minlength="5" maxlength="2000"></textarea></label>`,`data-action="notify" data-id="${esc(id)}"`);return;}
   if(['block','unblock','delete-account'].includes(action)){const a=accounts.find(a=>a.id===id&&a.kind===kind);if(!a)return;form(action==='delete-account'?'Excluir acesso da conta':action==='block'?'Bloquear acesso':'Desbloquear acesso',`<p><strong>${esc(a.email)}</strong></p><p>${action==='delete-account'?'A exclusão do login é definitiva. Empresas, produtos, fotos e histórico permanecem. O e-mail fica livre para novo cadastro.':'As sessões serão encerradas. O bloqueio impede login e alterações; use a moderação para retirar conteúdos da vitrine.'}</p>${reasonField}${action==='delete-account'?'<label>Digite o e-mail da conta<input name="confirmEmail" type="email" required autocomplete="off"></label>':''}`,`data-action="${action}" data-id="${esc(id)}" data-kind="${kind}" data-version="${a.version}"`);return;}
   if(action==='cleanup-start'){form('Conferir limpeza de contas','<p>Primeiro será mostrada a lista exata. A limpeza preserva empresas, produtos, fotos e os administradores.</p><label>E-mail do administrador a preservar<input name="preserveEmail" type="email" required value="'+esc(operatorEmail||'')+'"></label>','data-action="cleanup-preview"');return;}
   const p=products.find(p=>p.id===id);if(!p)return;
   if(action==='product'){openDialog(p.title,`<p>${esc(p.sellerName)} · ${esc(p.state)} · ${money(p.priceCents)}</p><p>${esc(p.condition)} · ${esc(p.category)} · ${esc(p.city)}</p><p class="preserve-lines">${esc(p.description)}</p><div class="lm-photos">${p.photos.map(photo=>`<img src="/api/local/product-photo?product=${encodeURIComponent(p.id)}&amp;id=${encodeURIComponent(photo)}" alt="Foto do anúncio ${esc(p.title)}">`).join('')}</div>${!p.deletedAt?`<form id="lm-form" data-action="moderate-product" data-id="${esc(id)}" data-version="${p.version}"><label>Decisão<select name="state">${p.state==='Em análise'?'<option value="Publicado">Aprovar e publicar</option><option value="Rejeitado">Recusar</option>':''}<option value="Pausado">Retirar da vitrine</option></select></label><label>Orientação (obrigatória ao recusar ou retirar)<textarea name="reason" maxlength="1000"></textarea></label><p role="alert"></p><button class="p-button primary">Salvar decisão</button></form>`:''}<h3>Histórico do anúncio</h3>${(p.history||[]).slice().reverse().map(h=>`<p>${date(h.at)} · ${esc(h.state)} ${esc(h.reason||'')}</p>`).join('')}`,true);return;}
   if(['delete-product','restore-product'].includes(action))form(action==='delete-product'?'Excluir anúncio':'Restaurar anúncio',`<p>${esc(p.title)}</p><p>${action==='delete-product'?'O anúncio e suas fotos saem da vitrine. É possível restaurar como rascunho.':'O anúncio volta como rascunho, sem publicação automática. Itens vendidos continuam encerrados.'}</p>${reasonField}`,`data-action="${action}" data-id="${esc(id)}" data-version="${p.version}"`);
  }catch(err){toast(err.message,true);}
 });
 document.addEventListener('submit',async e=>{const f=e.target;if(!active||f.id!=='lm-form')return;e.preventDefault();const b=f.querySelector('button');b.disabled=true;
  try {const data={...Object.fromEntries(new FormData(f)),action:f.dataset.action,id:f.dataset.id,kind:f.dataset.kind,version:Number(f.dataset.version)};
   if(data.action==='cleanup-preview'){preview=await api('/api/portal/local-control','POST',data);form('Revisar exclusão definitiva',`<p>${esc(preview.message)}</p><h3>${preview.remove.length} contas serão excluídas</h3><ul>${preview.remove.map(a=>`<li>${esc(a.email)} · ${esc(a.type)}</li>`).join('')}</ul><h3>Acessos preservados</h3><ul>${preview.preserved.map(a=>`<li>${esc(a.email)} · ${esc(a.type)}</li>`).join('')}</ul><h3>${preview.businesses.length} cadastros preservados sem alterações</h3><ul>${preview.businesses.map(a=>`<li>${esc(a.name)} · ${esc(a.state)}</li>`).join('')}</ul><label>Digite EXCLUIR CONTAS<input name="confirm" required autocomplete="off"></label>`,'data-action="cleanup"');return;}
   if(data.action==='cleanup')Object.assign(data,{digest:preview?.digest,preserveEmail:preview?.preserveEmail});
   if(data.action==='notify')data.businessId=data.id;
   let endpoint='/api/portal/local-control';if(['moderate-product','delete-product','restore-product'].includes(data.action)){endpoint='/api/portal/local-products';data.action={'moderate-product':'moderate','delete-product':'delete','restore-product':'restore'}[data.action];}
   const result=await api(endpoint,'POST',data);closeDialog();toast(data.action==='cleanup'?result.removed+' contas excluídas. Cadastros preservados.':data.action==='notify'?'Notificação enviada ao portal.':'Alteração salva.');await refresh();
  }catch(err){f.querySelector('[role=alert]').textContent=err.message;}finally{b.disabled=false;}
 });
 document.addEventListener('input',e=>{if(active&&e.target.id==='lm-search')drawList();});document.addEventListener('change',e=>{if(active&&e.target.id==='lm-filter')drawList();});
 return {page,load,error(message){const panel=document.querySelector('#lm-panel');if(active&&panel){panel.hidden=false;panel.textContent=message;}},mount(value){active=value;++epoch;},notifyButton};
}
